const data = $input.first().json;

// Gemini jsonOutput:true retourne directement l'objet/tableau
// mais on gère aussi le cas string au cas où
let parsed;
if (typeof data === 'string') {
  const cleaned = data
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .replace(/`/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} else {
  parsed = data;
}

// Normaliser en tableau
const commands = Array.isArray(parsed) ? parsed : [parsed];

// Récupérer la transcription depuis le node Whisper
const transcription = $('Whisper Transcription').first().json.text || '';

// Vérifier si Gemini a retourné une erreur
if (commands.length === 1 && commands[0].error) {
  return [{
    json: {
      status: 'error',
      code: 'COMMAND_NOT_RECOGNIZED',
      message: 'Commande non reconnue : ' + commands[0].error,
      transcription: transcription
    }
  }];
}

// Succès
return [{
  json: {
    status: 'success',
    transcription: transcription,
    commands: commands
  }
}];
